def fibonacci(n: int) -> int:
    """Return the nth Fibonacci number.

    fibonacci(0) = 0
    fibonacci(1) = 1
    fibonacci(n) = fibonacci(n-1) + fibonacci(n-2)

    If n is 0 or 1, return n directly. Otherwise, return the sum of fibonacci(n-1) and fibonacci(n-2) recursively.
