def word_frequency(text: str) -> dict[str, int]:
    frequency = {}
    words = text.split()
    for word in words:
        word = ''.join(e for e in word if e.isalnum()).lower()
        if word:
            frequency[word] = frequency.get(word, 0) + 1
    return frequency
